const MANIFEST = {
  "type": "Experience.ParallaxDepth",
  "description": "Multi-layer parallax with scroll-linked transforms, depth perception, and elegant motion",
  "editorElement": {
    "selector": ".parallax-depth",
    "displayName": "Parallax Depth Scene",
    "archetype": "container",
    "data": {
      "headline": {
        "dataType": "text",
        "displayName": "Headline",
        "defaultValue": "IMMERSIVE DEPTH",
        "group": "Content"
      },
      "subheadline": {
        "dataType": "text",
        "displayName": "Subheadline",
        "defaultValue": "Scroll to explore the layers",
        "group": "Content"
      },
      "layerCount": {
        "dataType": "select",
        "displayName": "Number of Layers",
        "defaultValue": "5",
        "options": ["3", "4", "5", "6", "7"],
        "group": "Layout"
      },
      "parallaxIntensity": {
        "dataType": "select",
        "displayName": "Parallax Intensity",
        "defaultValue": "1.0",
        "options": ["0.5", "0.75", "1.0", "1.25", "1.5"],
        "group": "Animation"
      },
      "scaleEffect": {
        "dataType": "booleanValue",
        "displayName": "Enable Scale Effect",
        "defaultValue": "true",
        "group": "Animation"
      },
      "rotateEffect": {
        "dataType": "booleanValue",
        "displayName": "Enable Rotation Effect",
        "defaultValue": "true",
        "group": "Animation"
      },
      "opacityEffect": {
        "dataType": "booleanValue",
        "displayName": "Enable Opacity Fade",
        "defaultValue": "true",
        "group": "Animation"
      },
      "blurEffect": {
        "dataType": "booleanValue",
        "displayName": "Enable Depth Blur",
        "defaultValue": "true",
        "group": "Animation"
      },
      "smoothing": {
        "dataType": "select",
        "displayName": "Motion Smoothing",
        "defaultValue": "0.1",
        "options": ["0.05", "0.1", "0.15", "0.2"],
        "group": "Animation"
      },
      "sceneHeight": {
        "dataType": "select",
        "displayName": "Scene Height (vh)",
        "defaultValue": "300",
        "options": ["200", "250", "300", "400", "500"],
        "group": "Layout"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#18181B",
        "group": "Colors"
      },
      "layer1Color": {
        "dataType": "color",
        "displayName": "Layer 1 (Back)",
        "defaultValue": "#27272A",
        "group": "Colors"
      },
      "layer2Color": {
        "dataType": "color",
        "displayName": "Layer 2",
        "defaultValue": "#3F3F46",
        "group": "Colors"
      },
      "layer3Color": {
        "dataType": "color",
        "displayName": "Layer 3",
        "defaultValue": "#52525B",
        "group": "Colors"
      },
      "layer4Color": {
        "dataType": "color",
        "displayName": "Layer 4",
        "defaultValue": "#71717A",
        "group": "Colors"
      },
      "layer5Color": {
        "dataType": "color",
        "displayName": "Layer 5 (Front)",
        "defaultValue": "#A1A1AA",
        "group": "Colors"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#FAFAFA",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Accent Color",
        "defaultValue": "#E4E4E7",
        "group": "Colors"
      },
      "headlineFontSize": {
        "dataType": "number",
        "displayName": "Headline Size (px)",
        "defaultValue": 72,
        "group": "Typography"
      },
      "fontWeight": {
        "dataType": "select",
        "displayName": "Font Weight",
        "defaultValue": "300",
        "options": ["300", "400", "500"],
        "group": "Typography"
      },
      "letterSpacing": {
        "dataType": "select",
        "displayName": "Letter Spacing",
        "defaultValue": "0.1em",
        "options": ["0em", "0.05em", "0.1em", "0.15em", "0.2em"],
        "group": "Typography"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const headline = config?.headline || 'IMMERSIVE DEPTH';
  const subheadline = config?.subheadline || 'Scroll to explore the layers';
  const layerCount = parseInt(config?.layerCount || '5');
  const parallaxIntensity = parseFloat(config?.parallaxIntensity || '1.0');
  const scaleEffect = config?.scaleEffect !== false;
  const rotateEffect = config?.rotateEffect !== false;
  const opacityEffect = config?.opacityEffect !== false;
  const blurEffect = config?.blurEffect !== false;
  const smoothing = parseFloat(config?.smoothing || '0.1');
  const sceneHeight = parseInt(config?.sceneHeight || '300');
  const backgroundColor = config?.backgroundColor || '#18181B';
  const textColor = config?.textColor || '#FAFAFA';
  const accentColor = config?.accentColor || '#E4E4E7';
  const headlineFontSize = parseInt(config?.headlineFontSize || '72');
  const fontWeight = config?.fontWeight || '300';
  const letterSpacing = config?.letterSpacing || '0.1em';

  const layerColors = React.useMemo(() => {
    const colors = [
      config?.layer1Color || '#27272A',
      config?.layer2Color || '#3F3F46',
      config?.layer3Color || '#52525B',
      config?.layer4Color || '#71717A',
      config?.layer5Color || '#A1A1AA',
      config?.layer5Color || '#D4D4D8',
      config?.layer5Color || '#E4E4E7'
    ];
    return colors.slice(0, layerCount);
  }, [config?.layer1Color, config?.layer2Color, config?.layer3Color, config?.layer4Color, config?.layer5Color, layerCount]);

  const containerRef = React.useRef(null);
  const layerRefs = React.useRef([]);
  const textRef = React.useRef(null);
  const scrollProgressRef = React.useRef(0);
  const currentValuesRef = React.useRef({ layers: [], text: { y: 0, scale: 1, opacity: 1 } });
  const animationFrameRef = React.useRef(null);

  const prefersReducedMotion = React.useMemo(() => {
    return typeof window !== 'undefined'
      ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
      : false;
  }, []);

  const shapes = React.useMemo(() => {
    const shapeTypes = ['circle', 'square', 'rectangle', 'diamond', 'triangle'];
    return Array.from({ length: layerCount }, (_, i) => ({
      type: shapeTypes[i % shapeTypes.length],
      size: 80 + i * 40,
      offsetX: (i % 2 === 0 ? 1 : -1) * (20 + i * 15),
      offsetY: i * 30,
      rotation: i * 15
    }));
  }, [layerCount]);

  React.useEffect(() => {
    if (prefersReducedMotion) return;

    currentValuesRef.current.layers = shapes.map(() => ({
      y: 0, scale: 1, opacity: 1, blur: 0, rotate: 0
    }));

    const lerp = (start, end, factor) => start + (end - start) * factor;

    const updateTransforms = () => {
      const container = containerRef.current;
      if (!container) return;

      const rect = container.getBoundingClientRect();
      const viewportHeight = window.innerHeight;
      const scrollProgress = Math.max(0, Math.min(1, -rect.top / (rect.height - viewportHeight)));
      scrollProgressRef.current = scrollProgress;

      shapes.forEach((shape, index) => {
        const layer = layerRefs.current[index];
        if (!layer) return;

        const depth = (index + 1) / layerCount;
        const speed = depth * parallaxIntensity;

        const targetY = scrollProgress * speed * 300;
        const targetScale = scaleEffect ? 1 + scrollProgress * depth * 0.3 : 1;
        const targetOpacity = opacityEffect ? 1 - scrollProgress * depth * 0.5 : 1;
        const targetBlur = blurEffect ? scrollProgress * (1 - depth) * 8 : 0;
        const targetRotate = rotateEffect ? scrollProgress * depth * 30 : 0;

        const current = currentValuesRef.current.layers[index] || { y: 0, scale: 1, opacity: 1, blur: 0, rotate: 0 };

        const newY = lerp(current.y, targetY, smoothing);
        const newScale = lerp(current.scale, targetScale, smoothing);
        const newOpacity = lerp(current.opacity, targetOpacity, smoothing);
        const newBlur = lerp(current.blur, targetBlur, smoothing);
        const newRotate = lerp(current.rotate, targetRotate, smoothing);

        currentValuesRef.current.layers[index] = { y: newY, scale: newScale, opacity: newOpacity, blur: newBlur, rotate: newRotate };

        layer.style.transform = `translate3d(${shape.offsetX}px, ${newY + shape.offsetY}px, 0) scale(${newScale}) rotate(${shape.rotation + newRotate}deg)`;
        layer.style.opacity = newOpacity;
        layer.style.filter = `blur(${newBlur}px)`;
      });

      if (textRef.current) {
        const textTargetY = scrollProgress * 150;
        const textTargetScale = 1 + scrollProgress * 0.2;
        const textTargetOpacity = 1 - scrollProgress * 0.8;

        const textCurrent = currentValuesRef.current.text;
        const newTextY = lerp(textCurrent.y, textTargetY, smoothing);
        const newTextScale = lerp(textCurrent.scale, textTargetScale, smoothing);
        const newTextOpacity = lerp(textCurrent.opacity, textTargetOpacity, smoothing);

        currentValuesRef.current.text = { y: newTextY, scale: newTextScale, opacity: newTextOpacity };

        textRef.current.style.transform = `translate3d(0, ${newTextY}px, 0) scale(${newTextScale})`;
        textRef.current.style.opacity = newTextOpacity;
      }

      animationFrameRef.current = requestAnimationFrame(updateTransforms);
    };

    animationFrameRef.current = requestAnimationFrame(updateTransforms);

    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    };
  }, [shapes, layerCount, parallaxIntensity, scaleEffect, rotateEffect, opacityEffect, blurEffect, smoothing, prefersReducedMotion]);

  const renderShape = (shape, color) => {
    const baseStyle = {
      width: shape.size,
      height: shape.type === 'rectangle' ? shape.size * 0.6 : shape.size,
      backgroundColor: 'transparent',
      border: `2px solid ${color}`,
      boxSizing: 'border-box'
    };

    switch (shape.type) {
      case 'circle':
        return { ...baseStyle, borderRadius: '50%' };
      case 'square':
        return { ...baseStyle, borderRadius: '4px' };
      case 'rectangle':
        return { ...baseStyle, borderRadius: '4px' };
      case 'diamond':
        return { ...baseStyle, transform: 'rotate(45deg)', borderRadius: '4px' };
      case 'triangle':
        return {
          width: 0,
          height: 0,
          backgroundColor: 'transparent',
          borderLeft: `${shape.size / 2}px solid transparent`,
          borderRight: `${shape.size / 2}px solid transparent`,
          borderBottom: `${shape.size}px solid ${color}`,
          border: 'none',
          borderBottomWidth: shape.size,
          borderBottomStyle: 'solid',
          borderBottomColor: color,
          borderLeftWidth: shape.size / 2,
          borderLeftStyle: 'solid',
          borderLeftColor: 'transparent',
          borderRightWidth: shape.size / 2,
          borderRightStyle: 'solid',
          borderRightColor: 'transparent'
        };
      default:
        return baseStyle;
    }
  };

  return (
    <div
      ref={containerRef}
      className="parallax-depth"
      style={{
        position: 'relative',
        width: '100%',
        height: `${sceneHeight}vh`,
        backgroundColor: backgroundColor,
        overflow: 'hidden'
      }}
    >
      <div
        style={{
          position: 'sticky',
          top: 0,
          width: '100%',
          height: '100vh',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          perspective: '1000px'
        }}
      >
        {shapes.map((shape, index) => (
          <div
            key={index}
            ref={el => layerRefs.current[index] = el}
            style={{
              position: 'absolute',
              left: '50%',
              top: '50%',
              marginLeft: -shape.size / 2,
              marginTop: -shape.size / 2,
              willChange: 'transform, opacity, filter',
              ...renderShape(shape, layerColors[index])
            }}
          />
        ))}

        <div
          ref={textRef}
          style={{
            position: 'relative',
            zIndex: layerCount + 1,
            textAlign: 'center',
            willChange: 'transform, opacity'
          }}
        >
          <h1
            style={{
              fontSize: `clamp(32px, ${headlineFontSize}px, 10vw)`,
              fontWeight: fontWeight,
              letterSpacing: letterSpacing,
              color: textColor,
              margin: '0 0 16px 0',
              fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
              textTransform: 'uppercase'
            }}
          >
            {headline}
          </h1>
          <p
            style={{
              fontSize: '16px',
              fontWeight: '400',
              color: accentColor,
              margin: 0,
              opacity: 0.8,
              fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif'
            }}
          >
            {subheadline}
          </p>
        </div>

        <div
          style={{
            position: 'absolute',
            bottom: '40px',
            left: '50%',
            transform: 'translateX(-50%)',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            gap: '8px',
            opacity: 0.6
          }}
        >
          <span
            style={{
              fontSize: '12px',
              letterSpacing: '0.15em',
              textTransform: 'uppercase',
              color: textColor,
              fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif'
            }}
          >
            Scroll
          </span>
          <div
            style={{
              width: '1px',
              height: '40px',
              backgroundColor: textColor,
              opacity: 0.5,
              animation: prefersReducedMotion ? 'none' : 'scrollPulse 2s ease-in-out infinite'
            }}
          />
        </div>
      </div>

      <style>
        {`
          @keyframes scrollPulse {
            0%, 100% { transform: scaleY(1); opacity: 0.5; }
            50% { transform: scaleY(1.5); opacity: 1; }
          }
        `}
      </style>
    </div>
  );
}

