const MANIFEST = {
  "type": "Transitions.SmoothFade",
  "description": "Smooth fade transition overlay for seamless page transitions with customizable duration and color",
  "editorElement": {
    "selector": ".smooth-fade-transition",
    "displayName": "Smooth Fade Transition",
    "archetype": "container",
    "data": {
      "overlayColor": {
        "dataType": "color",
        "displayName": "Overlay Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors",
        "description": "Color of the transition overlay"
      },
      "duration": {
        "dataType": "select",
        "displayName": "Duration (ms)",
        "defaultValue": "800",
        "options": ["600", "800", "1000", "1200"],
        "group": "Animation",
        "description": "Total transition duration"
      },
      "easing": {
        "dataType": "select",
        "displayName": "Easing",
        "defaultValue": "ease-in-out",
        "options": ["ease-in-out", "ease-out", "ease-in"],
        "group": "Animation"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const overlayColor = config?.overlayColor || "#FFFFFF";
  const duration = parseInt(config?.duration || "800");
  const easing = config?.easing || "ease-in-out";

  const [isActive, setIsActive] = React.useState(false);
  const [opacity, setOpacity] = React.useState(0);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const activeDuration = prefersReducedMotion ? 0 : duration;

  // Expose trigger method globally
  React.useEffect(() => {
    if (typeof window !== 'undefined') {
      window.triggerSmoothFade = (onComplete) => {
        setIsActive(true);
        setOpacity(1);

        // Fade in
        setTimeout(() => {
          // Midpoint - execute callback (e.g., navigate)
          if (onComplete) onComplete();

          // Fade out
          setTimeout(() => {
            setOpacity(0);
            setTimeout(() => {
              setIsActive(false);
            }, activeDuration / 2);
          }, 50);
        }, activeDuration / 2);
      };
    }

    return () => {
      if (typeof window !== 'undefined') {
        delete window.triggerSmoothFade;
      }
    };
  }, [activeDuration]);

  if (!isActive && opacity === 0) return null;

  return (
    <>
      <div
        className="smooth-fade-transition"
        style={{
          position: 'fixed',
          top: 0,
          left: 0,
          width: '100vw',
          height: '100vh',
          backgroundColor: overlayColor,
          opacity: opacity,
          transition: prefersReducedMotion ? 'none' : `opacity ${activeDuration / 2}ms ${easing}`,
          zIndex: 9999,
          pointerEvents: isActive ? 'all' : 'none',
          willChange: 'opacity'
        }}
        aria-hidden="true"
      />

      <style>{`
        .smooth-fade-transition {
          -webkit-backface-visibility: hidden;
          backface-visibility: hidden;
        }
      `}</style>
    </>
  );
}

