      layerStagger: "0.5",
      perspective: "1200",
      fontSizeVW: "22",
      letterSpacingVW: "-0.2"
    },
    minimal: {
      numberOfLayers: "2",
      rotationDuration: "1.0",
      characterStagger: "0.1",
      layerStagger: "0.5",
      perspective: "800",
      fontSizeVW: "14",
      letterSpacingVW: "0"
    },
    dramatic: {
      numberOfLayers: "6",
      rotationDuration: "0.6",
      characterStagger: "0.12",
      layerStagger: "0.4",
      perspective: "600",
      fontSizeVW: "24",
      letterSpacingVW: "-1.0"
    },
    staccato: {
      numberOfLayers: "4",
      rotationDuration: "0.6",
      characterStagger: "0.15",
      layerStagger: "0.3",
      perspective: "700",
      fontSizeVW: "18",
      letterSpacingVW: "-0.6"
    },
    "smooth-flow": {
      numberOfLayers: "5",
      rotationDuration: "1.2",
      characterStagger: "0.06",
      layerStagger: "0.5",
      perspective: "1000",
      fontSizeVW: "20",
      letterSpacingVW: "-0.4"
    },
    hypnotic: {
      numberOfLayers: "6",
      rotationDuration: "0.8",
      characterStagger: "0.08",
      layerStagger: "0.45",
      perspective: "600",
      fontSizeVW: "20",
      letterSpacingVW: "-0.8"
    }
  };

  const selectedPreset = config?.preset || "classic";
  const presetConfig = presets[selectedPreset] || presets.classic;

  // Use preset values with manual overrides
  const text = config?.text || "SplitText";
  const numLayers = parseInt(config?.numberOfLayers || presetConfig.numberOfLayers);
  const rotationDuration = parseFloat(config?.rotationDuration || presetConfig.rotationDuration);
  const charStagger = parseFloat(config?.characterStagger || presetConfig.characterStagger);
  const layerStagger = parseFloat(config?.layerStagger || presetConfig.layerStagger);
  const perspective = parseInt(config?.perspective || presetConfig.perspective);
  const fontSizeVW = parseFloat(config?.fontSizeVW || presetConfig.fontSizeVW);
  const letterSpacingVW = parseFloat(config?.letterSpacingVW || presetConfig.letterSpacingVW);
  const fontWeight = config?.fontWeight || "500";
  const bgColor = config?.backgroundColor || "#FFFFFF";
  const textColor = config?.textColor || "#212529";

  const [isVisible, setIsVisible] = React.useState(false);
  const containerRef = React.useRef(null);

  // Calculate depth for transform origin (exact replica of original: -width/8)
  const depth = typeof window !== 'undefined' ? -window.innerWidth / 8 : -200;

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  // Split text into characters
  const characters = text.split('').map((char, idx) => ({
    char: char === ' ' ? '\u00A0' : char,
    index: idx
  }));

  // Visibility observer
  React.useEffect(() => {
    if (prefersReducedMotion) {
      setIsVisible(true);
      return;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setIsVisible(true);
          }
        });
      },
      { threshold: 0.1 }
    );

    if (containerRef.current) {
      observer.observe(containerRef.current);
    }

    return () => observer.disconnect();
  }, [prefersReducedMotion]);

  return (
    <>
      <style>
        {`
          @keyframes rollCharacter {
            from {
              transform: rotateX(-90deg);
            }
            to {
              transform: rotateX(90deg);
            }
          }

          .roll-char {
            display: inline-block;
            backface-visibility: hidden;
            transform-style: preserve-3d;
          }

          .roll-line {
            animation: none;
          }

          .roll-line.active {
            animation-name: none;
          }

          .roll-line.active .roll-char {
            animation: rollCharacter linear infinite;
          }
        `}
      </style>

      <div
        ref={containerRef}
        className="rolling-text-replica"
        style={{
          position: 'relative',
          width: '100%',
          height: '100%',
          minHeight: '400px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          backgroundColor: bgColor,
          overflow: 'hidden',
          padding: '60px 20px'
        }}
      >
        {/* Container for text tube */}
        <div
          style={{
            position: 'relative',
            width: '100%',
            height: `${fontSizeVW * 1.3}vw`,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center'
          }}
        >
          {/* Multiple overlaid text lines */}
          {[...Array(numLayers)].map((_, layerIndex) => (
            <div
              key={layerIndex}
              className={`roll-line ${isVisible ? 'active' : ''}`}
              style={{
                position: 'absolute',
                top: '50%',
                left: '50%',
                transform: 'translate(-50%, -50%)',
                fontSize: `${fontSizeVW}vw`,
                fontWeight,
                letterSpacing: `${letterSpacingVW}vw`,
                color: textColor,
                whiteSpace: 'nowrap',
                lineHeight: 1,
                margin: 0,
                perspective: `${perspective}px`,
                transformStyle: 'preserve-3d',
                textAlign: 'center',
                visibility: isVisible ? 'visible' : 'hidden'
              }}
            >
              {characters.map((item, charIndex) => {
                const totalDuration = rotationDuration;
                const charDelay = charIndex * charStagger;
                const lineDelay = layerIndex * layerStagger;
                const totalDelay = charDelay + lineDelay;

                return (
                  <span
                    key={charIndex}
                    className="roll-char"
                    style={prefersReducedMotion ? {
                      display: 'inline-block'
                    } : {
                      animationDuration: `${totalDuration}s`,
                      animationDelay: `${totalDelay}s`,
                      transformOrigin: `50% 50% ${depth}px`
                    }}
                  >
                    {item.char}
                  </span>
                );
              })}
            </div>
          ))}
        </div>
      </div>
    </>
  );
}
